-- Appended after the migration in a single transaction, always rolled back
CREATE TEMP TABLE hospital_test_ids(cafe uuid,actor uuid,product uuid,category uuid,cash uuid,card uuid,shift uuid,warehouse uuid,item uuid,cash_before numeric,card_before numeric);
INSERT INTO hospital_test_ids SELECT '2e08901c-5aac-4bec-8c97-a135058e508b','96097d66-6764-423d-bcd4-bc2f146c5994',gen_random_uuid(),gen_random_uuid(),(SELECT a.id FROM public.bf_accounts a WHERE a.cafe_id='2e08901c-5aac-4bec-8c97-a135058e508b' AND a.active AND a.is_cashier_drawer LIMIT 1),(SELECT id FROM public.bf_accounts WHERE cafe_id='2e08901c-5aac-4bec-8c97-a135058e508b' AND active AND kind='pos' LIMIT 1),gen_random_uuid(),(SELECT id FROM public.bf_warehouses WHERE cafe_id='2e08901c-5aac-4bec-8c97-a135058e508b' AND active LIMIT 1),gen_random_uuid(),0,0;
INSERT INTO public.hospital_store_settings(cafe_id,enabled) SELECT cafe,true FROM hospital_test_ids;
INSERT INTO public.menu_categories(id,cafe_id,name,sort_order,visible) SELECT category,cafe,'Hospital rollback fixture',999,true FROM hospital_test_ids;
INSERT INTO public.menu_products(id,cafe_id,category_id,name,price,available,catalog_kind,commerce_details) SELECT product,cafe,category,'Hospital rollback product',10,true,'product','{"menuPriceRange":{"min":10,"max":15}}' FROM hospital_test_ids;
ALTER TABLE hospital_test_ids ADD COLUMN option_product uuid DEFAULT gen_random_uuid();
ALTER TABLE hospital_test_ids ADD COLUMN foreign_product uuid;
UPDATE hospital_test_ids SET foreign_product=(SELECT id FROM public.menu_products WHERE cafe_id='3813425d-db13-4d30-8b82-9d41aad12e36' AND deleted_at IS NULL LIMIT 1);
ALTER TABLE hospital_test_ids ADD COLUMN message_jobs_before bigint;
UPDATE hospital_test_ids t SET message_jobs_before=(SELECT count(*) FROM public.bf_customer_message_jobs WHERE cafe_id=t.cafe);
INSERT INTO public.menu_products(id,cafe_id,category_id,name,price,price_options,available,catalog_kind) SELECT option_product,cafe,category,'Hospital numeric option product',10,ARRAY[10,14]::numeric[],true,'product' FROM hospital_test_ids;
UPDATE public.bf_accounts SET transaction_fee_percent=2,fee_vat_rate=15,monthly_subscription=0,linked_bank_id=(SELECT id FROM public.bf_accounts WHERE cafe_id='2e08901c-5aac-4bec-8c97-a135058e508b' AND kind='bank' AND active LIMIT 1) WHERE id=(SELECT card FROM hospital_test_ids);
-- Existing test-tenant shifts are temporarily closed only inside this rolled-back fixture
UPDATE public.bf_shifts SET status='closed',closed_at=now() WHERE cafe_id='2e08901c-5aac-4bec-8c97-a135058e508b' AND status IN('open','handover');
INSERT INTO public.bf_shifts(id,cafe_id,user_id,account_id,opening_cash,expected_cash) SELECT shift,cafe,actor,cash,0,0 FROM hospital_test_ids;
INSERT INTO public.bf_items(id,cafe_id,name,sku,unit,cost_mode) SELECT item,cafe,'Hospital fixture stock','HOSP-'||item,'unit','full' FROM hospital_test_ids;
INSERT INTO public.bf_stock(cafe_id,item_id,warehouse_id,quantity,average_cost,value,cost_known) SELECT cafe,item,warehouse,100,3,300,true FROM hospital_test_ids;
INSERT INTO public.bf_item_product_links(cafe_id,item_id,product_id,quantity) SELECT cafe,item,product,1 FROM hospital_test_ids;
GRANT SELECT ON hospital_test_ids TO authenticated,service_role;
UPDATE hospital_test_ids t SET cash_before=(SELECT coalesce(sum(debit-credit),0) FROM public.bf_journal WHERE cafe_id=t.cafe AND account_id=t.cash),card_before=(SELECT coalesce(sum(debit-credit),0) FROM public.bf_journal WHERE cafe_id=t.cafe AND account_id=t.card);
SELECT set_config('request.jwt.claim.sub',actor::text,true) FROM hospital_test_ids;
SELECT set_config('request.jwt.claim.role','authenticated',true);
SET LOCAL ROLE authenticated;
DO $$
DECLARE t record;o jsonb;request uuid:=gen_random_uuid();cmd uuid:=gen_random_uuid();payload jsonb;res jsonb;party uuid;debt jsonb;before_count integer;counter jsonb;collection_request uuid:=gen_random_uuid();collection_payload jsonb;catalog_count integer;
BEGIN
 SELECT * INTO t FROM hospital_test_ids;
 IF public.hospital_access_enabled(t.cafe) IS DISTINCT FROM true THEN RAISE EXCEPTION 'ASSERT cashier access';END IF;
 payload:=jsonb_build_object('customerName','Fixture request','phone','966500000001','floor','2','clinic','Clinic A','doctor','Doctor A','notes','','language','en','items',jsonb_build_array(jsonb_build_object('productId',t.product,'quantity',2)));
 o:=public.hospital_counter_order(t.cafe,request,payload);
 IF (o->>'total')::numeric<>20 OR (o->>'totalMax')::numeric<>30 OR (o->>'needsPriceConfirmation')::boolean IS DISTINCT FROM true THEN RAISE EXCEPTION 'ASSERT preserved descriptive range';END IF;
 IF public.hospital_counter_order(t.cafe,request,payload)->>'id'<>o->>'id' THEN RAISE EXCEPTION 'ASSERT submit idempotency';END IF;
 BEGIN PERFORM public.hospital_counter_order(t.cafe,request,payload||'{"floor":"3"}'::jsonb);RAISE EXCEPTION 'ASSERT changed request allowed';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'HOSPITAL_REQUEST_CHANGED' THEN RAISE;END IF;END;
 BEGIN PERFORM public.hospital_order_manage(t.cafe,(o->>'id')::uuid,gen_random_uuid(),'checkout','{}');RAISE EXCEPTION 'ASSERT invalid checkout allowed';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'HOSPITAL_INVALID_PAYMENT' THEN RAISE;END IF;END;
 payload:=jsonb_build_object('paymentMethod','credit','debtorType','doctor','debtorName','Hospital fixture doctor','debtorPhone','966500000001','warehouseId',t.warehouse,'shiftId',t.shift,'confirmedPrices',jsonb_build_array(jsonb_build_object('index',0,'unitPrice',12)));
 BEGIN PERFORM public.hospital_order_manage(t.cafe,(o->>'id')::uuid,gen_random_uuid(),'checkout',payload||'{"confirmedPrices":[{"index":0,"unitPrice":999}]}');RAISE EXCEPTION 'ASSERT out of range allowed';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'HOSPITAL_CONFIRM_PRICES' THEN RAISE;END IF;END;
 res:=public.hospital_order_manage(t.cafe,(o->>'id')::uuid,cmd,'checkout',payload);
 IF res->>'paymentStatus'<>'credit' OR res->>'financeDocumentId' IS NULL THEN RAISE EXCEPTION 'ASSERT deferred invoice';END IF;
 SELECT x INTO counter FROM jsonb_array_elements(public.hospital_orders_read(t.cafe)) x WHERE x->>'id'=o->>'id';
 IF (counter->'items'->0->>'unitPrice')::numeric<>12 OR (counter->'items'->0->>'maxUnitPrice')::numeric<>12 OR (counter->'items'->0->>'quotedMaxUnitPrice')::numeric<>15 THEN RAISE EXCEPTION 'ASSERT invoiced line actual price and retained quote';END IF;
 IF public.hospital_order_manage(t.cafe,(o->>'id')::uuid,cmd,'checkout',payload)->>'financeDocumentId'<>res->>'financeDocumentId' THEN RAISE EXCEPTION 'ASSERT checkout idempotency';END IF;
 SELECT x INTO debt FROM jsonb_array_elements(public.hospital_debts_read(t.cafe)) x WHERE x->>'name'='Hospital fixture doctor';party:=(debt->>'id')::uuid;
 IF (debt->>'balance')::numeric<>24 OR (debt->'documents'->0->>'outstanding')::numeric<>24 THEN RAISE EXCEPTION 'ASSERT receivable amount';END IF;
 BEGIN PERFORM public.brand_finance_execute(t.cafe,'settlement',jsonb_build_object('documentId',res->>'financeDocumentId','amount',1,'accountId',t.cash,'shiftId',t.shift),gen_random_uuid());RAISE EXCEPTION 'ASSERT direct cashier settlement bypass';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 collection_payload:=jsonb_build_object('partyId',party,'amount',10,'paymentMethod','cash','accountId',t.cash,'shiftId',t.shift,'note','Rollback collection');
 BEGIN PERFORM public.hospital_debt_collect(t.cafe,gen_random_uuid(),collection_payload||'{"amount":25}');RAISE EXCEPTION 'ASSERT overpayment allowed';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'HOSPITAL_OVERPAYMENT' THEN RAISE;END IF;END;
 counter:=public.hospital_debt_collect(t.cafe,collection_request,collection_payload);
 IF (counter->>'balance')::numeric<>14 THEN RAISE EXCEPTION 'ASSERT cash collection';END IF;
 IF (public.hospital_debt_collect(t.cafe,collection_request,collection_payload)->>'duplicate')::boolean IS DISTINCT FROM true THEN RAISE EXCEPTION 'ASSERT collection idempotency';END IF;
 PERFORM public.hospital_debt_collect(t.cafe,gen_random_uuid(),collection_payload||jsonb_build_object('amount',14,'paymentMethod','card','accountId',t.card));
 SELECT x INTO debt FROM jsonb_array_elements(public.hospital_debts_read(t.cafe)) x WHERE x->>'id'=party::text;
 IF (debt->>'balance')::numeric<>0 OR jsonb_array_length(debt->'receipts')<>2 OR (debt->'documents'->0->>'outstanding')::numeric<>0 THEN RAISE EXCEPTION 'ASSERT card collection and statement';END IF;
 PERFORM public.hospital_order_manage(t.cafe,(o->>'id')::uuid,gen_random_uuid(),'prepare','{}');
 PERFORM public.hospital_order_manage(t.cafe,(o->>'id')::uuid,gen_random_uuid(),'ready','{}');
 counter:=public.hospital_order_manage(t.cafe,(o->>'id')::uuid,gen_random_uuid(),'complete','{}');
 IF counter->>'status'<>'completed' THEN RAISE EXCEPTION 'ASSERT lifecycle';END IF;
 BEGIN PERFORM public.hospital_order_manage(t.cafe,(o->>'id')::uuid,gen_random_uuid(),'cancel','{"note":"not allowed"}');RAISE EXCEPTION 'ASSERT invoiced cancel allowed';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'HOSPITAL_INVALID_STATE' THEN RAISE;END IF;END;
 BEGIN PERFORM public.hospital_orders_read('3813425d-db13-4d30-8b82-9d41aad12e36');RAISE EXCEPTION 'ASSERT cross tenant allowed';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 BEGIN PERFORM public.hospital_order_submit('test-cafe',gen_random_uuid(),'{}',repeat('a',64));RAISE EXCEPTION 'ASSERT authenticated public submit RPC allowed';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 RAISE NOTICE 'Hospital authenticated flow passed';
END $$;
RESET ROLE;
DO $$ DECLARE t record;s numeric;c numeric;BEGIN
 SELECT * INTO t FROM hospital_test_ids;
 SELECT quantity INTO s FROM public.bf_stock WHERE cafe_id=t.cafe AND item_id=t.item AND warehouse_id=t.warehouse;
 IF s<>98 THEN RAISE EXCEPTION 'ASSERT original stock engine once';END IF;
 IF EXISTS(SELECT document_id FROM public.bf_journal WHERE cafe_id=t.cafe AND document_id IN(SELECT finance_document_id FROM public.hospital_orders WHERE cafe_id=t.cafe) GROUP BY document_id HAVING sum(debit-credit)<>0) THEN RAISE EXCEPTION 'ASSERT balanced journal';END IF;
 SELECT sum(debit-credit) INTO c FROM public.bf_journal WHERE cafe_id=t.cafe AND account_id=t.cash;
 IF c-t.cash_before<>10 THEN RAISE EXCEPTION 'ASSERT cash account';END IF;
 SELECT sum(debit-credit) INTO c FROM public.bf_journal WHERE cafe_id=t.cafe AND account_id=t.card;
 IF c-t.card_before<>14 THEN RAISE EXCEPTION 'ASSERT card account';END IF;
 IF EXISTS(SELECT 1 FROM hospital_private.checkout_quotes) THEN RAISE EXCEPTION 'ASSERT no staged prices left';END IF;
 IF EXISTS(SELECT 1 FROM hospital_private.collection_context) THEN RAISE EXCEPTION 'ASSERT no staged collection left';END IF;
 IF NOT EXISTS(SELECT 1 FROM public.bf_terminal_fee_charges f JOIN public.bf_documents d ON d.id=f.source_document_id WHERE f.cafe_id=t.cafe AND d.shift_id=t.shift AND d.kind='settlement' AND f.base_amount=14 AND f.fee=0.28 AND f.tax=0.04) THEN RAISE EXCEPTION 'ASSERT original card receipt fee accrual';END IF;
 IF (SELECT count(*) FROM public.bf_documents WHERE cafe_id=t.cafe AND shift_id=t.shift AND kind='settlement')<>2 THEN RAISE EXCEPTION 'ASSERT original shift receipt linkage';END IF;
 IF (SELECT count(*) FROM public.bf_customer_message_jobs WHERE cafe_id=t.cafe)<>t.message_jobs_before THEN RAISE EXCEPTION 'ASSERT no customer messages';END IF;
 RAISE NOTICE 'Hospital original ledger/stock passed';
END $$;
DO $$ DECLARE t record;p jsonb;o jsonb;cp jsonb;receipt jsonb;party uuid;BEGIN
 SELECT * INTO t FROM hospital_test_ids;
 p:=jsonb_build_object('language','en','items',jsonb_build_array(jsonb_build_object('productId',t.option_product,'quantity',1,'priceOptionIndex',1)));
 o:=public.hospital_counter_order(t.cafe,gen_random_uuid(),p);
 IF (o->>'total')::numeric<>14 OR (o->>'totalMax')::numeric<>14 OR (o->'items'->0->>'priceOptionIndex')::integer<>1 THEN RAISE EXCEPTION 'ASSERT actual numeric option price';END IF;
 BEGIN PERFORM public.hospital_counter_order(t.cafe,gen_random_uuid(),p||jsonb_build_object('items',jsonb_build_array(jsonb_build_object('productId',t.option_product,'quantity',1,'priceOptionIndex',2))));RAISE EXCEPTION 'ASSERT option bounds';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'HOSPITAL_CHOOSE_OPTION' THEN RAISE;END IF;END;
 BEGIN PERFORM public.hospital_counter_order(t.cafe,gen_random_uuid(),p||jsonb_build_object('items',jsonb_build_array(jsonb_build_object('productId',t.foreign_product,'quantity',1))));RAISE EXCEPTION 'ASSERT foreign product allowed';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'HOSPITAL_PRODUCT_UNAVAILABLE' THEN RAISE;END IF;END;
 cp:=jsonb_build_object('paymentMethod','credit','debtorType','clinic','debtorName','Hospital fixture clinic','warehouseId',t.warehouse,'shiftId',t.shift,'confirmedPrices',jsonb_build_array(jsonb_build_object('index',0,'unitPrice',14)));
 UPDATE public.bf_shifts SET supervisor_paused=true WHERE id=t.shift;
 BEGIN PERFORM public.hospital_order_manage(t.cafe,(o->>'id')::uuid,gen_random_uuid(),'checkout',cp);RAISE EXCEPTION 'ASSERT paused credit checkout';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'HOSPITAL_SHIFT_REQUIRED' THEN RAISE;END IF;END;
 UPDATE public.bf_shifts SET supervisor_paused=false WHERE id=t.shift;
 receipt:=public.hospital_order_manage(t.cafe,(o->>'id')::uuid,gen_random_uuid(),'checkout',cp);
 SELECT party_id INTO party FROM public.bf_documents WHERE id=(receipt->>'financeDocumentId')::uuid;
 IF (SELECT details->>'hospitalDebtorType' FROM public.bf_parties WHERE id=party)<>'clinic' THEN RAISE EXCEPTION 'ASSERT clinic debtor';END IF;
 p:=jsonb_build_object('partyId',party,'amount',1,'paymentMethod','cash','accountId',t.cash,'shiftId',t.shift);
 UPDATE public.bf_settings SET closed_through=(now() AT TIME ZONE 'Asia/Riyadh')::date WHERE cafe_id=t.cafe;
 BEGIN PERFORM public.hospital_debt_collect(t.cafe,gen_random_uuid(),p);RAISE EXCEPTION 'ASSERT financial period closed';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'HOSPITAL_PERIOD_CLOSED' THEN RAISE;END IF;END;
 UPDATE public.bf_settings SET closed_through=NULL WHERE cafe_id=t.cafe;
 INSERT INTO public.bf_gl_periods(cafe_id,period_start,period_end,closed) VALUES(t.cafe,(now() AT TIME ZONE 'Asia/Riyadh')::date,(now() AT TIME ZONE 'Asia/Riyadh')::date,true);
 BEGIN PERFORM public.hospital_debt_collect(t.cafe,gen_random_uuid(),p);RAISE EXCEPTION 'ASSERT GL period closed';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'HOSPITAL_PERIOD_CLOSED' THEN RAISE;END IF;END;
 UPDATE public.bf_gl_periods SET closed=false WHERE cafe_id=t.cafe AND period_start=(now() AT TIME ZONE 'Asia/Riyadh')::date;
 UPDATE public.bf_shifts SET supervisor_paused=true WHERE id=t.shift;
 BEGIN PERFORM public.hospital_debt_collect(t.cafe,gen_random_uuid(),p);RAISE EXCEPTION 'ASSERT paused collection';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'HOSPITAL_SHIFT_REQUIRED' THEN RAISE;END IF;END;
 UPDATE public.bf_shifts SET supervisor_paused=false WHERE id=t.shift;
END $$;
-- Ordinary finance operations retain their authoritative prices and job guards
SET LOCAL ROLE authenticated;
DO $$ DECLARE t record;p jsonb;r jsonb;BEGIN
 SELECT * INTO t FROM hospital_test_ids;
 p:=jsonb_build_object('accountId',t.cash,'shiftId',t.shift,'warehouseId',t.warehouse,'expectedTotal',10,'lines',jsonb_build_array(jsonb_build_object('productId',t.product,'quantity',1,'price',0.01,'expectedUnitPrice',10,'hospitalLineIndex',0)));
 r:=public.brand_finance_execute(t.cafe,'sale',p,gen_random_uuid());
 PERFORM set_config('hospital_test.receipt_id',r->>'id',true);
 BEGIN INSERT INTO hospital_private.checkout_quotes(cafe_id,request_id,actor_id,transaction_id,lines) VALUES(t.cafe,gen_random_uuid(),t.actor,txid_current(),'[]');RAISE EXCEPTION 'ASSERT client can stage quote';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 BEGIN INSERT INTO hospital_private.collection_context(cafe_id,request_id,actor_id,transaction_id,payload) VALUES(t.cafe,gen_random_uuid(),t.actor,txid_current(),'{}');RAISE EXCEPTION 'ASSERT client can stage collection';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
END $$;
RESET ROLE;
DO $$ DECLARE doc uuid:=current_setting('hospital_test.receipt_id')::uuid;BEGIN
 IF (SELECT total FROM public.bf_documents WHERE id=doc) IS DISTINCT FROM 10 OR (SELECT unit_price FROM public.bf_document_lines WHERE document_id=doc) IS DISTINCT FROM 10 THEN RAISE EXCEPTION 'ASSERT normal sale server price despite forged hospital index';END IF;
END $$;
SELECT set_config('request.jwt.claim.sub',(SELECT owner_user_id::text FROM public.cafes WHERE id=(SELECT cafe FROM hospital_test_ids)),true);
DO $$ DECLARE t record;doc uuid;r jsonb;BEGIN
 SELECT * INTO t FROM hospital_test_ids;
 SELECT d.id INTO doc FROM public.bf_documents d JOIN public.bf_parties p ON p.id=d.party_id WHERE d.cafe_id=t.cafe AND d.kind='sale' AND p.name='Hospital fixture clinic';
 r:=public.brand_finance_execute(t.cafe,'settlement',jsonb_build_object('documentId',doc,'amount',1,'accountId',t.cash),gen_random_uuid());
 IF (brand_finance_private.document_state(t.cafe,doc)->>'outstanding')::numeric IS DISTINCT FROM 13 THEN RAISE EXCEPTION 'ASSERT ordinary authorized settlement';END IF;
 IF (SELECT shift_id FROM public.bf_documents WHERE id=(r->>'id')::uuid) IS NOT NULL THEN RAISE EXCEPTION 'ASSERT ordinary settlement unchanged shift';END IF;
END $$;
SELECT set_config('request.jwt.claim.sub',actor::text,true) FROM hospital_test_ids;
SET LOCAL ROLE service_role;
DO $$ DECLARE t record;o jsonb;payload jsonb;r uuid:=gen_random_uuid();BEGIN
 SELECT * INTO t FROM hospital_test_ids;
 payload:=jsonb_build_object('customerName','Public fixture','phone','966500000001','floor','1','clinic','Clinic B','doctor','','notes','','language','ar','items',jsonb_build_array(jsonb_build_object('productId',t.product,'quantity',1,'unitPrice',0.01)));
 o:=public.hospital_order_submit('test-cafe',r,payload,repeat('c',64));
 IF (o->>'total')::numeric<>10 OR (o->>'totalMax')::numeric<>15 THEN RAISE EXCEPTION 'ASSERT client price ignored';END IF;
 IF o ? 'phone' OR o ? 'items' THEN RAISE EXCEPTION 'ASSERT receipt private';END IF;
 IF public.hospital_order_submit('test-cafe',r,payload,repeat('c',64))->>'id'<>o->>'id' THEN RAISE EXCEPTION 'ASSERT public idempotency';END IF;
 BEGIN PERFORM public.hospital_order_submit('test-cafe',gen_random_uuid(),payload||jsonb_build_object('items',jsonb_build_array(jsonb_build_object('productId',t.foreign_product,'quantity',1))),repeat('c',64));RAISE EXCEPTION 'ASSERT public foreign product allowed';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'HOSPITAL_PRODUCT_UNAVAILABLE' THEN RAISE;END IF;END;
 BEGIN PERFORM public.hospital_order_submit('test-cafe',gen_random_uuid(),payload||'{"phone":"bad"}',repeat('c',64));RAISE EXCEPTION 'ASSERT invalid phone allowed';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'HOSPITAL_INVALID_INPUT' THEN RAISE;END IF;END;
 FOR i IN 1..14 LOOP PERFORM public.hospital_order_submit('test-cafe',gen_random_uuid(),payload,repeat('c',64));END LOOP;
 BEGIN PERFORM public.hospital_order_submit('test-cafe',gen_random_uuid(),payload,repeat('c',64));RAISE EXCEPTION 'ASSERT rate limit missing';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'HOSPITAL_RATE_LIMIT' THEN RAISE;END IF;END;
 RAISE NOTICE 'Hospital public ordering passed';
END $$;
RESET ROLE;
SELECT set_config('request.jwt.claim.sub',(SELECT owner_user_id::text FROM public.cafes WHERE id='3813425d-db13-4d30-8b82-9d41aad12e36'),true);
SET LOCAL ROLE authenticated;
DO $$ BEGIN
 IF EXISTS(SELECT 1 FROM public.hospital_orders) THEN RAISE EXCEPTION 'ASSERT cross tenant RLS row leak';END IF;
 BEGIN PERFORM public.hospital_orders_read('2e08901c-5aac-4bec-8c97-a135058e508b');RAISE EXCEPTION 'ASSERT cross tenant authenticated RPC';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
END $$;
RESET ROLE;
SET LOCAL ROLE anon;
DO $$ BEGIN
 BEGIN PERFORM * FROM public.hospital_orders;RAISE EXCEPTION 'ASSERT anonymous order access';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 BEGIN PERFORM public.hospital_orders_read('2e08901c-5aac-4bec-8c97-a135058e508b');RAISE EXCEPTION 'ASSERT anonymous inbox RPC';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 BEGIN PERFORM public.hospital_debts_read('2e08901c-5aac-4bec-8c97-a135058e508b');RAISE EXCEPTION 'ASSERT anonymous debt RPC';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 RAISE NOTICE 'Hospital anonymous ACL passed';
END $$;
RESET ROLE;
SELECT 'hospital integration rollback passed' AS result;
ROLLBACK;
